  "Findings for {routine}": "{routine}の指摘事項",
  "Choose the folder to review.": "レビューするフォルダを選んでください。",
  "This finding no longer exists.": "この指摘事項はもう存在しません。",
  "Choose why this finding is dismissed.":
    "この指摘事項を却下する理由を選んでください。",
