    "この指摘事項を却下する理由を説明してください。",
  "Polish a rough draft": "下書きを整える",
  "Word a tricky message": "言いにくいメッセージを書く",
  "Turn notes into a summary": "メモを要約にまとめる",
  "Spin a premise into a story": "設定を物語にふくらませる",
