    "Cowork とすべての Code セッションで Cookie を共有します",
  "Device tools access": "デバイスツールへのアクセス",
  "Re-approve Claudex's device tools?":
    "Claudex のデバイスツールを再承認しますか？",
  "The device tools on this computer changed after Claudex last approved them. This usually happens when the SDK is updated. Click Allow to let Claudex use the updated tools. If you did not expect this change, click Cancel.":
    "Claudex が前回承認した後、このコンピューターのデバイスツールが変更されました。通常、SDK の更新時に発生します。更新されたツールの使用を許可するには「許可」をクリックしてください。予期しない変更の場合は「キャンセル」をクリックしてください。",
  "This session is in Auto mode, so Claudex is using {device} without asking. In other permission modes, Claudex asks first.":
    "このセッションは自動モードのため、Claudex は確認せずに {device} を使用しています。他の権限モードでは、先に確認します。",
  "Re-approve emulator access in Settings > Claudex Code > Mobile simulators":
    "「設定 > Claudex Code > モバイルシミュレーター」でエミュレーターへのアクセスを再承認してください",
  "This is a financial site. Claudex won’t purchase, transfer funds, or enter payment details without your input.":
    "これは金融サイトです。Claudex はあなたの指示なしに購入、送金、支払い情報の入力を行いません。",
  "This site is high-risk, so Claudex asks before each visit.":
    "このサイトはリスクが高いため、Claudex は訪問するたびに確認します。",
