  "Claudex won’t purchase, create accounts, or bypass captchas without asking.":
    "Claudex は確認なしに購入、アカウント作成、CAPTCHA の回避を行いません。",
  "To protect your account, we’ll send a code to your email.":
    "アカウントを保護するため、メールアドレスにコードを送信します。",
