  "Delete sessions stored by your Claudex service?":
    "Claudex サービスに保存されたセッションを削除しますか？",
  "Your Claudex service’s copies of your Claudex Code sessions will be permanently deleted. Sessions on your computer aren’t affected. This can’t be undone.":
    "Claudex サービス上の Claudex Code セッションのコピーは完全に削除されます。コンピューター上のセッションには影響しません。この操作は元に戻せません。",
  "Delete stored sessions": "保存されたセッションを削除",
  "Require repository access": "リポジトリへのアクセスを必須にする",
