    "共有したセッションに名前が表示されます。",
  "Sign in to Claudex again.": "Claudex に再度サインインしてください。",
  "A message is already waiting to be sent in this conversation. Send the next one after it.":
    "この会話には送信待ちのメッセージがあります。送信後に次のメッセージを送ってください。",
