  "No sessions to import": "インポートするセッションがありません",
  "Only sessions in your trusted folders can be imported, and there are none left to add.":
    "信頼済みフォルダー内のセッションのみインポートできます。追加できるセッションはありません。",
  "Importing sessions": "セッションをインポート中",
  "Imported 1 session": "1 件のセッションをインポートしました",
  "Imported {count} sessions": "{count} 件のセッションをインポートしました",
  "No sessions imported": "セッションはインポートされませんでした",
