  "Find them in your session list.": "セッション一覧で確認できます。",
  "Your claude.ai export didn’t import":
    "claude.ai のエクスポートをインポートできませんでした",
  "Claude.ai export": "Claude.ai のエクスポート",
  "Suggested tasks": "提案されたタスク",
  "Put “{title}” in the message box": "「{title}」をメッセージボックスに入れる",
  "Delete “{title}”": "「{title}」を削除",
  "Couldn’t take this task off the list. It will show up again.":
    "このタスクをリストから削除できませんでした。再び表示されます。",
  "Couldn’t delete this task. Try again.":
    "このタスクを削除できませんでした。もう一度お試しください。",
  "Task backlog unavailable; try again":
    "タスクバックログを利用できません。もう一度お試しください",
  'Allow "{artifact}" to run a scheduled task?':
    "「{artifact}」にスケジュール済みタスクの実行を許可しますか？",
  'The live artifact "{artifact}" wants to run the scheduled task "{task}".':
    "ライブアーティファクト「{artifact}」がスケジュール済みタスク「{task}」を実行しようとしています。",
  "Don't ask again for this task": "このタスクでは今後確認しない",
  "Import from link": "リンクからインポート",
  "Import shared artifact": "共有アーティファクトをインポート",
  "Paste a shared artifact link to add a copy to your artifacts.":
    "共有アーティファクトのリンクを貼り付けて、アーティファクトにコピーを追加します。",
  "Failed to import shared artifact.":
    "共有アーティファクトのインポートに失敗しました。",
  "Artifact library storage limit reached.":
    "アーティファクトライブラリのストレージ上限に達しました。",
  "Only regular files can be previewed.":
    "通常のファイルのみプレビューできます。",
  "This file resolves outside the conversation workspace.":
    "このファイルの実際のパスは会話のワークスペース外にあります。",
  "Allow all browser actions?": "すべてのブラウザー操作を許可しますか？",
  "This setting can put your data at risk.":
    "この設定によりデータが危険にさらされる可能性があります。",
  "Claudex will browse and interact with any website without asking. Applies to new sessions. This setting can put your data at risk.":
    "Claudex は確認せずにあらゆるウェブサイトを閲覧・操作します。新しいセッションに適用されます。この設定によりデータが危険にさらされる可能性があります。",
  "Claudex will take actions without asking for your permission, including on websites you haven’t approved.":
    "Claudex は、許可していないウェブサイトも含め、許可を求めずに操作を実行します。",
  "Your note for Claudex about this element":
    "この要素について Claudex に伝えるメモ",
