  "Resend email": "メールを再送信",
  "Use verification code to continue": "確認コードを使用して続行",
  "Enter this verification code where you first tried to sign in":
    "最初にログインを試みた画面で、この確認コードを入力してください",
  "Sign in here instead": "代わりにここでログイン",
  "SSH sessions": "SSHセッション",
  "Allowed connector tools": "許可されたコネクタツール",
  "Connector tools Claudex can use on an SSH host without a permission prompt.":
    "ClaudexがSSHホストで権限の確認なしに使用できるコネクタツール。",
  "Claudex can use each tool on the SSH host shown beside it without a permission prompt. Remove one and Claudex asks again next time.":
    "Claudexは各ツールの横に表示されているSSHホストで、権限の確認なしにそのツールを使用できます。削除すると、Claudexは次回また確認します。",
  "Nothing here yet. When you choose “Always allow” for a connector tool in an SSH session, it appears here.":
    "まだ何もありません。SSHセッションでコネクタツールに「常に許可」を選択すると、ここに表示されます。",
