  "Remove {tool} on {host}": "{host}の{tool}を削除",
  "Edit connection…": "接続を編集…",
  "Delete connection": "接続を削除",
  "Delete SSH connection?": "SSH接続を削除しますか？",
  "“{connectionName}” will be permanently deleted. This can’t be undone.":
    "「{connectionName}」は完全に削除されます。この操作は取り消せません。",
  Cut: "カット",
  "Use Mac clipboard when pasting": "ペースト時にMacのクリップボードを使用",
  "Rotate right": "右に回転",
  "Device pose": "デバイスの姿勢",
  "Half open": "半開き",
  "Rotation is not supported by this device.":
    "このデバイスは回転に対応していません。",
  "Editing is not supported by this device.":
    "このデバイスは編集に対応していません。",
  "Let Claudex verify your changes in the iOS Simulator on this Mac: running your app, driving it through flows, and capturing screenshots and recordings. You will be asked before Claudex uses each device. When off, Claudex doesn’t get its simulator tools, and you can still use the simulator in the app yourself.":
    "このMac上のiOS Simulatorで変更を確認できるようにClaudexを許可します。アプリの実行、フローを通じた操作、スクリーンショットと録画の取得が可能になります。Claudexが各デバイスを使用する前に確認を求められます。オフにすると、ClaudexはSimulatorツールを使用できなくなりますが、引き続きご自身でアプリ内のSimulatorをご利用いただけます。",
  "Let Claudex verify your changes in Android emulators on this Mac: running your app, driving it through flows, and capturing screenshots and recordings. You will be asked before Claudex uses each device. When off, Claudex doesn’t get its emulator tools, and you can still use the emulator in the app yourself.":
    "このMac上のAndroidエミュレーターで変更を確認できるようにClaudexを許可します。アプリの実行、フローを通じた操作、スクリーンショットと録画の取得が可能になります。Claudexが各デバイスを使用する前に確認を求められます。オフにすると、Claudexはエミュレーターツールを使用できなくなりますが、引き続きご自身でアプリ内のエミュレーターをご利用いただけます。",
  "Let Claudex verify your changes in Android emulators on this computer: running your app, driving it through flows, and capturing screenshots and recordings. You will be asked before Claudex uses each device. When off, Claudex doesn’t get its emulator tools, and you can still use the emulator in the app yourself.":
    "このコンピューター上のAndroidエミュレーターで変更を確認できるようにClaudexを許可します。アプリの実行、フローを通じた操作、スクリーンショットと録画の取得が可能になります。Claudexが各デバイスを使用する前に確認を求められます。オフにすると、Claudexはエミュレーターツールを使用できなくなりますが、引き続きご自身でアプリ内のエミュレーターをご利用いただけます。",
  "Couldn’t clear browsing data.": "閲覧データを消去できませんでした。",
  "Auto-updates": "自動更新",
  "Update feed": "更新フィード",
  "Update binaries": "更新バイナリ",
