    "Claudex Code セッション情報（{generatedAt}）",
  "Verified in the source directory. This is not a new Claudex security audit.":
    "提供元のディレクトリーで検証済みです。Claudex による新たなセキュリティ監査ではありません。",
  "Community listing. Review tool permissions before connecting.":
    "コミュニティ掲載です。接続前にツールの権限を確認してください。",
  "Community listing. Review tool permissions before installing.":
    "コミュニティ掲載です。インストール前にツールの権限を確認してください。",
  "You added this connector. Claudex has not reviewed it.":
    "追加したコネクターです。Claudex は審査していません。",
  "Community connectors are not a security guarantee. Only connect developers you trust.":
    "コミュニティコネクターは安全を保証しません。信頼できる開発者にのみ接続してください。",
  "Community extensions are not a security guarantee. Only install developers you trust.":
    "コミュニティ拡張機能は安全を保証しません。信頼できる開発者のものだけをインストールしてください。",
  "Community plugins are not a security guarantee. Only install developers you trust.":
    "コミュニティプラグインは安全を保証しません。信頼できる開発者のものだけをインストールしてください。",
  "Suite of tools for creating elaborate, multi-component Claudex HTML artifacts using modern frontend tooling.":
    "最新のフロントエンドツールを使用して、複雑な複数コンポーネントのClaudex HTMLアーティファクトを作成するためのツール群です。",
  "Claudex usage policy": "Claudex 利用ポリシー",
  "Only use connectors from developers you trust. Claudex does not control which tools developers make available and cannot verify that they will work as intended or that they won’t change.":
    "信頼できる開発者のコネクタのみを使用してください。Claudex は開発者が提供するツールを管理しておらず、意図どおりに動作することや変更されないことを保証できません。",
  "Claudex Sans": "Claudex Sans",
  "Not reviewed in the source directory": "提供元ディレクトリーで未審査",
  "Verified in the source directory": "提供元ディレクトリーで検証済み",
  "Not verified in the source directory": "提供元ディレクトリーで未検証",
  "Claudex Serif": "Claudex Serif",
  "An independent desktop client.": "独立したデスクトップクライアント。",
  "Internal only": "内部のみ",
  "Make sure you trust a plugin before installing or using it. Uploaded plugins are not controlled by Claudex, and Claudex cannot verify that they will work as intended. See each plugin’s homepage for more information.":
    "インストールや使用の前にプラグインが信頼できることを確認してください。アップロードされたプラグインはClaudexの管理下になく、意図どおり動作するか確認できません。詳細は各プラグインのホームページをご覧ください。",
  "Community marketplace": "コミュニティマーケットプレイス",
  "Plugins bundle skills, connectors and hooks. Browse community marketplaces or sync your own from a repository.":
    "プラグインにはスキル、コネクター、フックが含まれます。コミュニティマーケットを探すか、リポジトリーから自分のマーケットを同期できます。",
  "Your conversation export didn’t import":
    "会話のエクスポートをインポートできませんでした",
  Claudex: "Claudex",
