  "Search by name": "名前で検索",
  "Build connectors and plugins": "コネクタとプラグインを作る",
  "A connector is an MCP server: it speaks the Model Context Protocol over streamable HTTP, signs people in with OAuth or a token, and describes each tool’s inputs and effects plainly. A plugin bundles skills, connectors and instructions into one package. Add your connector as a custom connector under Customize → Connectors and try it in a chat before you send it with Submit to the directory.":
    "コネクタは MCP サーバーです。streamable HTTP で Model Context Protocol を話し、OAuth またはトークンでサインインさせ、各ツールの入力と動作をはっきり説明します。プラグインはスキル、コネクタ、指示を 1 つのパッケージにまとめたものです。カスタマイズ → コネクタでカスタムコネクタとして追加し、チャットで試してから「ディレクトリに提出」で送ってください。",
